INSERT INTO daily_reports (id, project_id, submitted_by, date, weather, temperature, workers_on_site, work_completed, issues, notes, photo_count, created_at) VALUES (1, 1, 5, '2026-09-25', 'Partly Cloudy', '24', 28, 'Completed casting of columns C3 and C4 on ground floor. Formwork struck for beam B1; concrete quality satisfactory. Backfilling completed on west elevation. Surface dressing applied to internal access road.', 'Delivery of steel Y16 bars from Devki Steel Mills delayed. Expected arrival: Tuesday 29 September. Site team adjusting schedule, working on columns C5 and C6 formwork in the meantime.', 'Client visited site at 11:00 AM. Generally satisfied with progress. Requested update on roofing material delivery timeline.', 6, '2026-10-05 13:00:38') ON CONFLICT DO NOTHING;
INSERT INTO daily_reports (id, project_id, submitted_by, date, weather, temperature, workers_on_site, work_completed, issues, notes, photo_count, created_at) VALUES (2, 1, 5, '2026-09-24', 'Light Rain', '21', 22, 'Plumbing rough-in continued, second floor east wing. Steel placement for columns C3 and C4 completed and checked. Carpenter team fabricating formwork for beams B4–B6.', 'Rain halted work at 14:30. Resumed at 15:45. No structural impact.', 'Safety inspection conducted by site engineer. All PPE compliant. Fire extinguisher near generator replaced.', 3, '2026-10-05 13:00:38') ON CONFLICT DO NOTHING;
